//! Direct PBR pass, reusing camera-v2 view/project/near clip. Output is tone-mapped (ACES fit, exposure 1.0), display-referred.
use super::{vertex_stream::Stream,lighting_stage::{Light,shade},pbr::Material};
use crate::{effects::Frame,camera_projection::{Camera,Vertex,clip}};

pub struct Output{pub frame:Frame,pub depth:Vec<f64>,pub covered:usize,pub clipped_triangles:usize}
/// Normals are world-space. Render geometry in world coordinates; camera has
/// positive-Z view convention. Direct GGX lighting, no textures/shadow/alpha composition.
/// ACES fitted curve (Narkowicz) with exposure multiply; output clamped to [0,1].
/// Display-referred tone map for the direct PBR pass; shade() itself stays linear HDR.
pub fn aces_tonemap(color:[f64;3],exposure:f64)->[f64;3]{color.map(|c|{let x=(c*exposure).max(0.);((x*(2.51*x+0.03))/(x*(2.43*x+0.59)+0.14)).clamp(0.,1.)})}
pub fn render(stream:&Stream,camera:&Camera,w:usize,h:usize,material:&Material,lights:&[Light])->Result<Output,String>{stream.validate()?;super::lighting_stage::validate(lights)?;let mesh=super::mesh::Mesh{positions:stream.vertices.iter().map(|v|v.position.map(|v|v as f64)).collect(),indices:stream.indices.clone()};camera.validate()?;if w==0||h==0||w>4096||h>4096{return Err("target1..4096 required".into());}let mut frame=Frame::try_new(w,h)?;let mut depth=vec![f64::INFINITY;w*h];let projection=Camera{eye:[0.;3],pan:0.,tilt:0.,roll:0.,..*camera};let mut clipped_triangles=0;
 let edge=|a:[f64;3],b:[f64;3],x:f64,y:f64|(b[0]-a[0])*(y-a[1])-(b[1]-a[1])*(x-a[0]);
 for indices in &mesh.indices{crate::guard::check();let mut vertices=Vec::with_capacity(3);for id in indices{let i=*id as usize;vertices.push(Vertex{position:camera.view(mesh.positions[i])?,attributes:stream.vertices[i].normal.iter().map(|v|*v as f64).chain(mesh.positions[i]).collect()});}let tri:[Vertex;3]=vertices.try_into().map_err(|_|"triangle conversion")?;let triangles=clip(tri,camera.near)?;clipped_triangles+=triangles.len();for t in triangles{let mut projected=[[0.;3];3];for i in 0..3{projected[i]=projection.project(t[i].position,w as u32,h as u32)?.ok_or("clipped vertex failed camera projection")?;}let area=edge(projected[0],projected[1],projected[2][0],projected[2][1]);if !area.is_finite(){return Err("projected triangle area overflow".into());}if area==0.0{continue;}
 let bounds=|axis:usize,limit:usize|{let lo=projected.iter().map(|p|p[axis]).fold(f64::INFINITY,f64::min).floor().clamp(0.,limit as f64) as usize;let hi=projected.iter().map(|p|p[axis]).fold(f64::NEG_INFINITY,f64::max).ceil().clamp(0.,limit as f64) as usize;(lo,hi)};let (x0,x1)=bounds(0,w);let(y0,y1)=bounds(1,h);
 for y in y0..y1{crate::guard::check();for x in x0..x1{let(sx,sy)=(x as f64+0.5,y as f64+0.5);let b=[edge(projected[1],projected[2],sx,sy)/area,edge(projected[2],projected[0],sx,sy)/area,edge(projected[0],projected[1],sx,sy)/area];if b.iter().any(|v|*v<0.){continue;}let inv_z=(0..3).map(|i|b[i]/projected[i][2]).sum::<f64>();if !inv_z.is_finite()||inv_z<=0.{return Err("inverse depth invalid".into());}let z=1.0/inv_z;let id=y*w+x;if !z.is_finite(){return Err("depth overflow".into());}if z>=depth[id]{continue;}let interp=|j:usize|(0..3).map(|i|b[i]*t[i].attributes[j]/projected[i][2]).sum::<f64>()/inv_z;let n=std::array::from_fn(|j|interp(j));let p=std::array::from_fn(|j|interp(j+3));let color=aces_tonemap(shade(material,p,n,camera.eye,lights)?,1.0);depth[id]=z;for j in 0..3{frame.d[id*4+j]=color[j] as f32;}frame.d[id*4+3]=1.;}}
 }}let covered=depth.iter().filter(|v|v.is_finite()).count();Ok(Output{frame,depth,covered,clipped_triangles})}
#[cfg(test)]mod tests{use super::*;use crate::threed::primitives::{generate,Primitive};
 fn fixture()->(Stream,Camera,Material,Vec<Light>){let g=generate(&Primitive::Sphere{radius:1.,longitude_slices:32,latitude_slices:16}).unwrap();(Stream{vertices:g.vertices,indices:g.indices},Camera{eye:[0.,0.,-4.],pan:0.,tilt:0.,roll:0.,sensor_height:24.,focal_length:35.,near:0.1},Material{albedo:[0.5,0.2,0.1],metallic:0.2,roughness:0.4},vec![Light::Directional{travel_direction:[0.2,0.4,1.],radiance:[2.;3]}])}
 #[test]fn cpu_lit_stream_finite_and_nonblack(){let(s,c,m,l)=fixture();let o=render(&s,&c,128,72,&m,&l).unwrap();assert!(o.covered>0);assert!(o.frame.d.iter().all(|v|v.is_finite()&&*v>=0.));assert!(o.frame.d.chunks_exact(4).any(|p|p[0]>0.));}
 #[test]#[ignore="1080p direct PBR rows after numeric gate"]fn render_pbr_contact_sources(){use std::io::Write;let dir=std::env::var("KIMO_PBR_FRAMES").expect("directory");std::fs::create_dir_all(&dir).unwrap();let(s,c,mut m,l)=fixture();for metallic in [0.,1.]{for roughness in [0.1,0.4,0.8]{m.metallic=metallic;m.roughness=roughness;let o=render(&s,&c,1920,1080,&m,&l).unwrap();let path=format!("{dir}/metal-{metallic}-rough-{roughness}.png");let mut child=std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","rawvideo","-pix_fmt","rgba","-s","1920x1080","-i","-","-frames:v","1",&path]).stdin(std::process::Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&crate::render::to_rgba8(&o.frame)).unwrap();assert!(child.wait().unwrap().success());}}}
}
